class VoidBrowserController {
  Future<void> Function(String path)? _scrollToTrack;
  bool? Function(String path)? _isTrackVisible;

  /// Bumped when either the scroll position changes or the browser completes a
  /// frame that could have affected row visibility. The parent uses it to
  /// rebuild conditional UI (e.g. now-playing jump affordances).
  final ValueNotifier<int> visibilityTick = ValueNotifier<int>(0);

  /// Centre the row for [path] in view; no-op when the browser is unmounted.
  Future<void> scrollToTrack(String path) async =>
      await _scrollToTrack?.call(path);

  /// Returns whether [path]'s row currently overlaps the visible browser
  /// viewport.
  ///
  /// Returns `null` when the row (or viewport) isn't measurable yet.
  bool? isTrackVisible(String path) => _isTrackVisible?.call(path);

  void dispose() => visibilityTick.dispose();
}

